previewCss:
.darma-loader-darma-b11-printer-print { --accent: var(--loader-color, #3b82f6); --accent-2: var(--loader-secondary-color, #22d3ee); width: var(--loader-size, 88px); height: var(--loader-size, 88px); position: relative; }
.darma-loader-darma-b11-printer-print .darma-loader-darma-b11-printer-print__body { position: absolute; left: 14%; bottom: 20%; width: 72%; height: 38%; background: linear-gradient(#94a3b8, #475569); border-radius: 8px 8px 10px 10px; z-index: 2; }
.darma-loader-darma-b11-printer-print .darma-loader-darma-b11-printer-print__body::after { content: ''; position: absolute; bottom: 22%; left: 12%; width: 30%; height: 14%; border-radius: 3px; background: var(--accent-2); box-shadow: 0 0 calc(var(--loader-size, 88px) * .06) var(--accent-2); }
.darma-loader-darma-b11-printer-print .darma-loader-darma-b11-printer-print__paper { position: absolute; left: 28%; bottom: 57%; width: 44%; height: 0; background: #fff; border: 1px solid #cbd5e1; overflow: hidden; animation: darma-loader-darma-b11-printer-print-print calc(var(--loader-speed, 1s) * 2.4) ease-in-out infinite; }
.darma-loader-darma-b11-printer-print .darma-loader-darma-b11-printer-print__paper::before { content: ''; position: absolute; inset: 14% 12%; background: repeating-linear-gradient(var(--accent) 0 12%, transparent 12% 30%); }
@keyframes darma-loader-darma-b11-printer-print-print { 0% { height: 0; } 45%, 100% { height: 46%; } }

